Build a graph, see its score
Choose a direction, or none, for each pair of commute variables. The explorer adds up the graph’s Bayesian score from precomputed per-variable terms (Equation 2), on 3,000 simulated mornings with the BDeu prior. It reports how the graph compares with the true one, and whether the two are Markov equivalent. Start from the true graph, then try reversing storm–alert (equivalent, same score), reversing roadwork–jam, or adding extra edges.

sl = FileAttachment("data/ch05-scores.json").json()
pairs = {
  const ids = sl.nodes.map(d =&gt; d.id), out = [];
  for (let i = 0; i &lt; ids.length; i++) for (let j = i + 1; j &lt; ids.length; j++) out.push([ids[i], ids[j]]);
  return out;
}
viewof edges = Inputs.form(Object.fromEntries(pairs.map(([a, b]) =&gt; {
  const start = sl.truth[b].includes(a) ? `${a} → ${b}` : sl.truth[a].includes(b) ? `${b} → ${a}` : "none";
  return [a + b, Inputs.select(["none", `${a} → ${b}`, `${b} → ${a}`], {label: `${a} – ${b}`, value: start})];
})))























result = {
  // Rebuild the parent sets from the chosen edges.
  const parents = Object.fromEntries(sl.nodes.map(d =&gt; [d.id, []]));
  for (const choice of Object.values(edges)) if (choice !== "none") { const [u, , v] = choice.split(" "); parents[v].push(u); }
  // Acyclic? Repeatedly remove nodes whose parents are all removed (as in is_acyclic).
  let left = new Set(Object.keys(parents)), progress = true;
  while (progress) { progress = false;
    for (const x of [...left]) if (parents[x].every(p =&gt; !left.has(p))) { left.delete(x); progress = true; } }
  if (left.size) return {cyclic: true, parents};
  // Decomposable score: one precomputed term per variable.
  const score = d3.sum(Object.entries(parents), ([x, pa]) =&gt; sl.table[`${x}|${[...pa].sort().join(",")}`]);
  // Markov equivalence: compare skeletons and v-structures with the true graph.
  const skel = g =&gt; new Set(Object.entries(g).flatMap(([x, pa]) =&gt; pa.map(p =&gt; [p, x].sort().join(""))));
  const vstr = g =&gt; { const s = skel(g);
    return new Set(Object.entries(g).flatMap(([c, pa]) =&gt; pa.flatMap((a, i) =&gt; pa.slice(i + 1)
      .filter(b =&gt; !s.has([a, b].sort().join(""))).map(b =&gt; [a, b].sort().join("") + "&gt;" + c)))); };
  const same = (A, B) =&gt; A.size === B.size && [...A].every(e =&gt; B.has(e));
  const equivalent = same(skel(parents), skel(sl.truth)) && same(vstr(parents), vstr(sl.truth));
  return {cyclic: false, parents, score, diff: score - sl.trueScore, equivalent};
}







