Beta posterior explorer
Set a Beta prior with its pseudocounts, then add data. Watch the posterior move from the prior toward the data as the counts grow. With little data the prior dominates; with a lot, it barely matters.

viewof a0 = Inputs.range([0.5, 30], {step: 0.5, value: 1, label: "Prior α (pseudo-yes)"})
viewof b0 = Inputs.range([0.5, 30], {step: 0.5, value: 1, label: "Prior β (pseudo-no)"})
viewof yes = Inputs.range([0, 100], {step: 1, value: 3, label: "Observed yes"})
viewof no = Inputs.range([0, 100], {step: 1, value: 7, label: "Observed no"})






























beta = {
  // Evaluate densities on a grid and normalize numerically, so no special
  // functions are needed: density ∝ θ^(a-1) (1-θ)^(b-1).
  const grid = d3.range(0.0025, 1, 0.005);
  const shape = (a, b) =&gt; {
    const logs = grid.map(t =&gt; (a - 1) * Math.log(t) + (b - 1) * Math.log(1 - t));
    const top = d3.max(logs);                          // subtract the max to avoid overflow
    const vals = logs.map(l =&gt; Math.exp(l - top));
    const area = d3.sum(vals) * 0.005;
    return vals.map(v =&gt; v / area);
  };
  const prior = shape(a0, b0), post = shape(a0 + yes, b0 + no);
  const rows = grid.flatMap((t, i) =&gt; [{t, p: prior[i], curve: "Prior"}, {t, p: post[i], curve: "Posterior"}]);
  // 95% credible interval: where the posterior's running total crosses 2.5% and 97.5%.
  const cum = d3.cumsum(post.map(v =&gt; v * 0.005));
  const lo = grid[d3.bisectLeft(cum, 0.025)], hi = grid[d3.bisectLeft(cum, 0.975)];
  return {rows, lo, hi, mean: (a0 + yes) / (a0 + b0 + yes + no), ml: yes + no ? yes / (yes + no) : null};
}







