Would you take the gamble?
A coin flip pays $100 with the chance you set, and $0 otherwise. The alternative is a sure amount. Set your risk attitude: \(\lambda &gt; 0\) is risk averse, \(\lambda &lt; 0\) risk seeking, and \(\lambda = 0\) risk neutral. The curve is your utility of money; the certainty equivalent is where its height equals the gamble’s expected utility.

viewof lam = Inputs.range([-0.04, 0.06], {step: 0.005, value: 0.01, label: "Risk aversion λ"})
viewof pWin = Inputs.range([0, 1], {step: 0.05, value: 0.5, label: "Chance of winning $100"})
viewof sure = Inputs.range([0, 100], {step: 1, value: 40, label: "Sure amount ($)"})























risk = {
  // Exponential utility rescaled so U(0) = 0 and U(100) = 1; a straight line at λ = 0.
  const U = x =&gt; Math.abs(lam) &lt; 1e-9 ? x / 100 : (1 - Math.exp(-lam * x)) / (1 - Math.exp(-lam * 100));
  const Uinv = u =&gt; Math.abs(lam) &lt; 1e-9 ? 100 * u : -Math.log(1 - u * (1 - Math.exp(-lam * 100))) / lam;
  const eu = pWin * U(100);                 // U(0) = 0, so only the win contributes
  const ce = Uinv(eu);
  const curve = d3.range(0, 100.5, 1).map(x =&gt; ({x, u: U(x)}));
  return {U, eu, ce, curve, takeSure: U(sure) &gt; eu};
}







