Watch approximate value iteration
Pick a grid size and scrub through the iterations. The heat map is the approximate number of steps to the goal (minus the value) at each grid point. The path is what the greedy policy does from the start you choose, computed live from the grid shown. Early on the values are wrong almost everywhere, and cars wander. Watch the correct values spread outward from the goal as the iterations proceed, and compare the coarse and fine grids.

avi = FileAttachment("data/ch08-avi.json").json()
viewof n = Inputs.radio([11, 21, 41], {label: "Grid points per axis", value: 21})
viewof k = Inputs.select(avi.snapshots, {label: "After iteration", value: 400})
viewof x0 = Inputs.range([-1.2, 0.5], {step: 0.01, value: -0.5, label: "Start position"})
viewof v0 = Inputs.range([-0.07, 0.07], {step: 0.005, value: 0, label: "Start speed"})





































car = {
  const vals = avi.values[n][avi.snapshots.indexOf(k)];
  const clamp = (z, lo, hi) =&gt; Math.min(hi, Math.max(lo, z));
  // Mountain car dynamics (same as adm/problems/mountain_car.py).
  const step = ([x, v], a) =&gt; {
    const v2 = clamp(v + 0.001 * a - 0.0025 * Math.cos(3 * x), -0.07, 0.07);
    return [clamp(x + v2, -1.2, 0.6), v2];
  };
  // Bilinear interpolation on the n x n grid: vals[i * n + j] is x index i, v index j.
  const U = ([x, v]) =&gt; {
    const zx = (x + 1.2) / 1.8 * (n - 1), zv = (v + 0.07) / 0.14 * (n - 1);
    const i = clamp(Math.floor(zx), 0, n - 2), j = clamp(Math.floor(zv), 0, n - 2);
    const fx = clamp(zx - i, 0, 1), fv = clamp(zv - j, 0, 1);
    return (1 - fx) * (1 - fv) * vals[i * n + j] + (1 - fx) * fv * vals[i * n + j + 1]
         + fx * (1 - fv) * vals[(i + 1) * n + j] + fx * fv * vals[(i + 1) * n + j + 1];
  };
  // Greedy policy: one-step lookahead, -1 per step, value 0 once the goal is reached.
  const act = s =&gt; [-1, 0, 1].map(a =&gt; { const s2 = step(s, a); return {a, q: -1 + (s2[0] &gt;= 0.6 ? 0 : U(s2))}; })
                             .reduce((best, c) =&gt; c.q &gt; best.q ? c : best).a;
  const path = [[x0, v0]];
  while (path[path.length - 1][0] &lt; 0.6 && path.length &lt;= 500) path.push(step(path[path.length - 1], act(path[path.length - 1])));
  const cells = [];
  for (let i = 0; i &lt; n; i++) for (let j = 0; j &lt; n; j++)
    cells.push({x: -1.2 + 1.8 * i / (n - 1), v: -0.07 + 0.14 * j / (n - 1), steps: -vals[i * n + j]});
  return {path, cells, reached: path[path.length - 1][0] &gt;= 0.6};
}







