viewof th1 = Inputs.range([-0.1, 0.1], {step: 0.0025, value: 0, label: "θ₁ (position weight)"})
viewof th2 = Inputs.range([-0.1, 0.1], {step: 0.0025, value: 0, label: "θ₂ (offset)"})























cars = {
  const clamp = (z, lo, hi) =&gt; Math.min(hi, Math.max(lo, z));
  // Mountain car dynamics (as in adm/problems/mountain_car.py) under the switching rule.
  const paths = mtn.starts.map(([x0, v0]) =&gt; {
    let x = x0, v = v0; const path = [[x, v]];
    while (x &lt; 0.6 && path.length &lt;= mtn.cap) {
      const a = v + th1 * x + th2 &gt; 0 ? 1 : -1;
      v = clamp(v + 0.001 * a - 0.0025 * Math.cos(3 * x), -0.07, 0.07);
      x = clamp(x + v, -1.2, 0.6);
      path.push([x, v]);
    }
    return path;
  });
  const steps = paths.map(p =&gt; p[p.length - 1][0] &gt;= 0.6 ? p.length - 1 : mtn.cap + 1);
  const cells = [];
  mtn.th.forEach((a, i) =&gt; mtn.th.forEach((b, j) =&gt; cells.push({a, b, s: mtn.grid[i][j]})));
  return {paths, steps, mean: d3.mean(steps), escaped: steps.filter(s =&gt; s &lt;= mtn.cap).length, cells};
}







