What does a Dirichlet belief look like?
Set the counts observed for one state and action (“climb” at some position): how often it went up, stayed, or slipped. The chart shows the belief about each of the three probabilities (the Dirichlet’s marginals, uniform prior), and five probability vectors sampled from it, as posterior sampling would draw them.

viewof nUp = Inputs.range([0, 40], {step: 1, value: 2, label: "Went up"})
viewof nStay = Inputs.range([0, 40], {step: 1, value: 3, label: "Stayed"})
viewof nSlip = Inputs.range([0, 40], {step: 1, value: 0, label: "Slipped"})























dir = {
  // Uniform prior: alpha = 1 + counts. Marginal of component i is Beta(alpha_i, sum - alpha_i).
  const alpha = [1 + nUp, 1 + nStay, 1 + nSlip], total = d3.sum(alpha);
  const logFact = k =&gt; d3.sum(d3.range(1, k + 1), Math.log);     // log (k!) for integers
  const names = ["up", "stay", "slip"];
  const xs = d3.range(0.0025, 1, 0.005);
  const dens = names.flatMap((name, i) =&gt; {
    const a = alpha[i], b = total - alpha[i];
    const logB = logFact(a - 1) + logFact(b - 1) - logFact(a + b - 1);   // log Beta function
    return xs.map(x =&gt; ({name, x, y: Math.exp((a - 1) * Math.log(x) + (b - 1) * Math.log(1 - x) - logB)}));
  });
  // Dirichlet samples: independent Gamma(alpha_i) draws, normalized (seeded, so the page is stable).
  const rand = d3.randomLcg(42);
  const draws = d3.range(5).map(k =&gt; {
    const g = alpha.map(a =&gt; d3.randomGamma.source(rand)(a)());
    return names.map((name, i) =&gt; ({k: `sample ${k + 1}`, name, p: g[i] / d3.sum(g)}));
  }).flat();
  return {alpha, total, dens, draws, names, means: alpha.map(a =&gt; a / total)};
}
md`Predictive probabilities (posterior means): up **${dir.means[0].toFixed(3)}**, stay **${dir.means[1].toFixed(3)}**, slip **${dir.means[2].toFixed(3)}**.`
















