  const color = {domain: dir.names, range: ["#2a78d6", "#898781", "#eb6834"], legend: true};
  const left = Plot.plot({width: 330, height: 240, color, x: {domain: [0, 1], label: "probability"},
    y: {label: "belief density", grid: true}, style: {background: "#fcfcfb"},
    marks: [Plot.line(dir.dens, {x: "x", y: "y", stroke: "name", strokeWidth: 2})]});
