  const solve = (layout, phi) =&gt; {
    const grid = parkData.layouts[layout], n = parkData.rows * parkData.cols + 1, tr = parkData.trans[layout];
    const reward = s =&gt; s === n - 1 ? 0 : phi[parkData.terrain.indexOf(grid[Math.floor(s / parkData.cols)][s % parkData.cols])];
    let U = new Array(n).fill(0);
    for (let it = 0; it &lt; 500; it++)
      U = U.map((_, s) =&gt; Math.max(...tr[s].map(outs =&gt; reward(s) + parkData.gamma * d3.sum(outs, ([s2, p]) =&gt; p * U[s2]))));
    return U.map((_, s) =&gt; d3.maxIndex(tr[s].map(outs =&gt; reward(s) + parkData.gamma * d3.sum(outs, ([s2, p]) =&gt; p * U[s2]))));
  };
  // True value of a deterministic policy from the chosen start (iterative evaluation, true reward).
  const trueValue = (layout, pi, start) =&gt; {
    const grid = parkData.layouts[layout], n = parkData.rows * parkData.cols + 1, tr = parkData.trans[layout];
    const r = s =&gt; s === n - 1 ? 0 : parkData.phi_true[parkData.terrain.indexOf(grid[Math.floor(s / parkData.cols)][s % parkData.cols])];
    let U = new Array(n).fill(0);
    for (let it = 0; it &lt; 800; it++) U = U.map((_, s) =&gt; r(s) + parkData.gamma * d3.sum(tr[s][pi[s]], ([s2, p]) =&gt; p * U[s2]));
    return U[start];
  };
  const phi = [wPath, wGrass, wMud, wGate], start = startRow * parkData.cols;
  return ["A", "B"].map(layout =&gt; {
    const pi = solve(layout, phi), best = solve(layout, parkData.phi_true);
    return {layout, pi, value: trueValue(layout, pi, start), best: trueValue(layout, best, start)};
  });
}
